import{_ as a,H as t,f as r,i as l}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"加餐1｜前两章课后题答案","description":"","frontmatter":{},"headers":[{"level":2,"title":"热身赛 用 RAG 改造传统 MIS 系统","slug":"热身赛-用-rag-改造传统-mis-系统","link":"#热身赛-用-rag-改造传统-mis-系统","children":[{"level":3,"title":"第1节课","slug":"第1节课","link":"#第1节课","children":[]},{"level":3,"title":"第2节课","slug":"第2节课","link":"#第2节课","children":[]},{"level":3,"title":"第3节课","slug":"第3节课","link":"#第3节课","children":[]},{"level":3,"title":"第4节课","slug":"第4节课","link":"#第4节课","children":[]},{"level":3,"title":"第5节课","slug":"第5节课","link":"#第5节课","children":[]},{"level":3,"title":"第6节课","slug":"第6节课","link":"#第6节课","children":[]},{"level":3,"title":"第7节课","slug":"第7节课","link":"#第7节课","children":[]}]},{"level":2,"title":"初级篇 开启一个全新的 RAG 项目","slug":"初级篇-开启一个全新的-rag-项目","link":"#初级篇-开启一个全新的-rag-项目","children":[{"level":3,"title":"第8节课","slug":"第8节课","link":"#第8节课","children":[]},{"level":3,"title":"第9节课","slug":"第9节课","link":"#第9节课","children":[]},{"level":3,"title":"第10节课","slug":"第10节课","link":"#第10节课","children":[]}]}],"relativePath":"RAG系统实战课/加餐1｜前两章课后题答案.md","filePath":"RAG系统实战课/加餐1｜前两章课后题答案.md","lastUpdated":1779816165000}'),i={name:"RAG系统实战课/加餐1｜前两章课后题答案.md"};function n(s,e,h,o,p,g){return t(),r("div",null,[...e[0]||(e[0]=[l(`<h1 id="加餐1-前两章课后题答案" tabindex="-1">加餐1｜前两章课后题答案 <a class="header-anchor" href="#加餐1-前两章课后题答案" aria-label="Permalink to &quot;加餐1｜前两章课后题答案&quot;">​</a></h1><p>你好，我是叶伟民。今天是国庆假期第二天，首先祝你国庆快乐。到今天为止，课程前两章的内容已经更新完了，期间我也收到了不少同学的留言评论，也期待我们能够持续交流。</p><p>你可以借着假期这段时间来查漏补缺，我也推荐你多动手操练一下，这样能帮你更好地掌握前两章的知识。</p><p>为了方便你参考对照，这次加餐，我把前两章的思考题答案集中发布出来。建议你先自己尝试思考、回答问题以后，再参考我提供的分析思路和问题解答，这样学习效果会更好。</p><h2 id="热身赛-用-rag-改造传统-mis-系统" tabindex="-1">热身赛 用 RAG 改造传统 MIS 系统 <a class="header-anchor" href="#热身赛-用-rag-改造传统-mis-系统" aria-label="Permalink to &quot;热身赛 用 RAG 改造传统 MIS 系统&quot;">​</a></h2><h3 id="第1节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/806091" target="_blank" rel="noreferrer">第1节课</a> <a class="header-anchor" href="#第1节课" aria-label="Permalink to &quot;[第1节课](https://time.geekbang.org/column/article/806091)&quot;">​</a></h3><p>Q：既然一个 RAG 应用无法一步到位，那么我们如何度过 RAG 应用不成熟的早期阶段呢？</p><p>A：找愿意拥抱新技术的用户作为种子用户，进行试点。一般来说，经过三个月或者半年，一个RAG应用就能在种子用户的帮助下成熟起来，可以推广给更多人用。在这个过程中，我们可以使用第7、19、20节课的知识点收集数据和反馈、制定评估指标，然后再使用第四章的知识点改进我们的RAG应用。</p><h3 id="第2节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/806130" target="_blank" rel="noreferrer">第2节课</a> <a class="header-anchor" href="#第2节课" aria-label="Permalink to &quot;[第2节课](https://time.geekbang.org/column/article/806130)&quot;">​</a></h3><p>Q：如果用户与 AI 进行了一万次对话（一万次应该超出了目前所有大模型的记忆上限），那么我们的应用如何处理呢？</p><p>A：好记性不如烂笔头，我们可以每十次对话就把前面的对话记录存进外部的知识库（数据库），然后根据相关问题从知识库里面检索出对应的对话记录，这样这个问题就转化为RAG问题了。</p><h3 id="第3节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/806979" target="_blank" rel="noreferrer">第3节课</a> <a class="header-anchor" href="#第3节课" aria-label="Permalink to &quot;[第3节课](https://time.geekbang.org/column/article/806979)&quot;">​</a></h3><p>Q：如果给了大模型一个示例，它还是无法正确输出。这时候有什么办法解决呢？</p><p>A：如果一个示例不够，那就给多几个示例，但是每个示例应该是不一样的。另外，就像我们编程不可能把所有代码写在一个函数或者类里面，整个系统也不可能只有一个提示语。我们可以像编程划分模块、类、函数一样，按模块、场景划分提示语，再根据不同模块、场景调用不同的提示语。这样的话，我们就能在不同的提示语里面给予对应的示例。</p><h3 id="第4节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/807070" target="_blank" rel="noreferrer">第4节课</a> <a class="header-anchor" href="#第4节课" aria-label="Permalink to &quot;[第4节课](https://time.geekbang.org/column/article/807070)&quot;">​</a></h3><p>Q：前面“调用大模型”一节中的 ernie_client_id 和 ernie_client_secret 是十分重要的，如果泄露出去会带来很大的麻烦，甚至带来金钱损失。所以在实际工作中这两个参数的具体值不应该直接写在代码里面，那么应该如何处理呢？</p><p>A：可以放在环境变量里面。然后在代码中调用环境变量来获取它们。具体实现代码如下。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ernie_client_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.getenv(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;baiduclientid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ernie_client_secret </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.getenv(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;baiduclientsecret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="第5节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/807859" target="_blank" rel="noreferrer">第5节课</a> <a class="header-anchor" href="#第5节课" aria-label="Permalink to &quot;[第5节课](https://time.geekbang.org/column/article/807859)&quot;">​</a></h3><p>Q：这节课的代码只支持销售管理模块，如果需要支持其他模块，例如生产管理模块，那该如何处理？</p><p>A：很简单，就两点。第一，把生产管理各个模块加进选项里面。第二，把生产管理的示例添加进示例里面。</p><h3 id="第6节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/808306" target="_blank" rel="noreferrer">第6节课</a> <a class="header-anchor" href="#第6节课" aria-label="Permalink to &quot;[第6节课](https://time.geekbang.org/column/article/808306)&quot;">​</a></h3><p>Q：如果有多个用户使用这个系统，那么如何判断哪条对话记录属于哪个用户？</p><p>A：我们可以在对话记录表里面多添加一个“用户”字段，然后根据这个字段来判断。</p><h3 id="第7节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/809016" target="_blank" rel="noreferrer">第7节课</a> <a class="header-anchor" href="#第7节课" aria-label="Permalink to &quot;[第7节课](https://time.geekbang.org/column/article/809016)&quot;">​</a></h3><p>Q：为了教学方便，代码中的数据库字段都是使用中文，但是实际工作中基本是英文，所以传给大模型的都会是英文而不是中文，如何处理这个问题？</p><p>A：可以写一个函数，建立一个中英文对照表，将英文替换成中文，这样大模型接收的数据库记录就变成中文了。</p><h2 id="初级篇-开启一个全新的-rag-项目" tabindex="-1"><strong>初级篇 开启一个全新的 RAG 项目</strong> <a class="header-anchor" href="#初级篇-开启一个全新的-rag-项目" aria-label="Permalink to &quot;**初级篇 开启一个全新的 RAG 项目**&quot;">​</a></h2><h3 id="第8节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/809066" target="_blank" rel="noreferrer">第8节课</a> <a class="header-anchor" href="#第8节课" aria-label="Permalink to &quot;[第8节课](https://time.geekbang.org/column/article/809066)&quot;">​</a></h3><p>Q：前面说到，在这个实战案例中，用户提问实际就是：今天的 CNET 有哪些新闻？请把这些新闻摘要并翻译成中文发给我。那么如果 CNET 每天的新闻有很多，有上千条的新闻，那么用户提问改成什么会比较合适呢？我们的实战案例又需要添加什么步骤呢？</p><p>A：很简单，假设你只对AI的新闻感兴趣，那么可以将提问改成：今天的CNET有哪些新闻 <strong>是跟AI相关的</strong>？请把这些新闻进行摘要，并翻译成中文发给我。</p><p>这时候我们的实战案例就需要多加一个步骤，从当天的所有新闻里面检索出跟AI相关的新闻，再交给AI处理，最终返回给用户。</p><h3 id="第9节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/809371" target="_blank" rel="noreferrer">第9节课</a> <a class="header-anchor" href="#第9节课" aria-label="Permalink to &quot;[第9节课](https://time.geekbang.org/column/article/809371)&quot;">​</a></h3><p>Q：前面我们添加了一个示例，当用户提问：前天的 CNET 新闻有哪些？应该返回序号、日期。那么如果用户提问：最近一周的 CNET 新闻有哪些？这时应该如何处理呢？</p><p>A：我们可以按照 <a href="https://time.geekbang.org/column/article/807859" target="_blank" rel="noreferrer">第5节课</a> 的学到的知识点，添加更多示例。</p><h3 id="第10节课" tabindex="-1"><a href="https://time.geekbang.org/column/article/810048" target="_blank" rel="noreferrer">第10节课</a> <a class="header-anchor" href="#第10节课" aria-label="Permalink to &quot;[第10节课](https://time.geekbang.org/column/article/810048)&quot;">​</a></h3><p>Q：在新闻简报这个案例背景下，我们是否需要对所有文章都进行文本摘要呢？</p><p>A：如果一篇文章很短，例如很多“字越少，事越大”的那类新闻，就没有必要进行文本摘要了。所以在文本摘要之前，我们还需要对文章内容长度进行判断，只有长于最低长度的时候，才进行文本摘要。</p><p>第11～13节课都是动手练习的题目，相信经过练习，你也会对相关的知识点掌握得更加扎实。以上就是这次加餐的全部内容。下节课开始，我们将迎来第三个实战项目，辅助工单系统，敬请期待。</p>`,39)])])}const d=a(i,[["render",n]]);export{k as __pageData,d as default};
